// Turn Jev's answers into flat fields your CRM can store.
// Jev's guess goes in timezone_inferred, so it never overwrites a value a person entered.
const THRESHOLD = 0.8; // minimum confidence to write the time zone automatically

return $input.all().map((item) => {
  const { answers, model, ...lead } = item.json;
  const tz = answers.timezone;
  const confident = tz.choice !== 'unknown' && tz.confidence >= THRESHOLD;
  return {
    json: {
      ...lead,
      timezone_inferred: tz.choice,
      timezone_confidence: Number(tz.confidence.toFixed(2)),
      timezone_status: confident ? 'auto' : 'review',
      decision_maker_probability: Number(answers.is_decision_maker.noul.toFixed(2)),
      lead_fit_score: Number(answers.lead_fit.score.toFixed(2)), // 0 = not a fit, 3 = ideal
      jev_model: model,
    },
  };
});
